const recentExportRequests = `-- name: RecentExportRequests :many
SELECT requested_at FROM privacy_requests
WHERE user_id = $1 AND kind = 'export' AND requested_at > $2::timestamptz ORDER BY requested_at
`

type RecentExportRequestsParams struct {
	UserID uuid.UUID
	Since  time.Time
}

func (q *Queries) RecentExportRequests(ctx context.Context, arg RecentExportRequestsParams) ([]time.Time, error) {
	rows, err := q.db.Query(ctx, recentExportRequests, arg.UserID, arg.Since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []time.Time{}
	for rows.Next() {
		var requested_at time.Time
		if err := rows.Scan(&requested_at); err != nil {
			return nil, err
		}
		items = append(items, requested_at)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

