const takeExport = `-- name: TakeExport :one
DELETE FROM privacy_exports WHERE request_id = $1 AND expires_at > $2::timestamptz RETURNING user_id, ciphertext
`

type TakeExportParams struct {
	RequestID uuid.UUID
	Now       time.Time
}

type TakeExportRow struct {
	UserID     uuid.UUID
	Ciphertext []byte
}

// One download only: the archive is deleted as it is read.
func (q *Queries) TakeExport(ctx context.Context, arg TakeExportParams) (TakeExportRow, error) {
	row := q.db.QueryRow(ctx, takeExport, arg.RequestID, arg.Now)
	var i TakeExportRow
	err := row.Scan(&i.UserID, &i.Ciphertext)
	return i, err
}

